#!/usr/bin/env python3
"""v1.7.0 results.tex patch batch B: mechanism (ΔPE unification), strata
reframing, adaptive-rule number fixes, closing integration."""
import sys

P = "/home/z/my-project/paper/sections/results.tex"
txt = open(P).read()
orig = txt

def rep(start_anchor, end_anchor, new_text, label):
    global txt
    i = txt.find(start_anchor)
    if i < 0:
        sys.exit(f"PATCH {label}: start anchor not found: {start_anchor[:60]!r}")
    j = txt.find(end_anchor, i + len(start_anchor))
    if j < 0:
        sys.exit(f"PATCH {label}: end anchor not found: {end_anchor[:60]!r}")
    txt = txt[:i] + new_text + txt[j:]
    print(f"patched: {label}")

# ---- P4: mechanism paragraph (ΔPE unified to within-family + downgrades) ----
MECH = r"""The dataset decomposition carries the mechanism, with two cautions stated up front: each cell rests on twenty questions per model (nineteen for LSAT-LR), and all gains below are the within-family margins of Table~\ref{tab:expand_ds} ($\Delta$SC $=$ SC-6 $-$ S1, $\Delta$PE $=$ PE-6 $-$ PE-1), with single-call difficulty margins reported alongside wherever they are large. On Agnes3.0-Flash's SAT-Math subset, answer-space diversity is close to exhausted: six samples of the original stem move accuracy from 61.7\% to 60.0\% ($\Delta$SC $-$1.7), so resampling re-confirms the same wrong computations, while the paraphrase ensemble recovers the subset almost entirely (PE-6 100.0\%, $\Delta$PE +17.5); all eight SAT-Math questions on which SC-6 and PE-6 disagree are won by the paraphrase vote. Because SAT-Math paraphrases vary the instruction wording rather than the stem, part of this cell is plausibly an instruction effect rather than an aggregation effect: the paraphrase single call already sits 20.8 points above S1 there (PE-1 82.5 against 61.7), which suggests that the canonical directive to answer without explanation is itself suboptimal for quantitative items and that some instruction variants elicit more careful behaviour. The within-family margin is net of this base-rate shift, but separating instruction quality from aggregation proper would require re-running self-consistency under the best instruction variant, which we leave to future work. GSM8K shows the same direction in weaker form (PE-6 100.0\%, $\Delta$PE +2.5 on a floor of 95.0\%). LogiQA is the mirror image for this model: paraphrases are 11.7 points harder at the single-call level (PE-1 63.3 against S1 75.0), indicating that restating a verbal-reasoning stem can shift the reasoning problem itself, and there the sample vote is the only condition that aggregates a gain (SC-6 90.0\%, $\Delta$SC +15.0 against $\Delta$PE +1.7; five of the seven flips favour SC). TruthfulQA is the one dataset where its six-sample vote actively hurts (SC-6 65.0 against S1 70.8), consistent with the development-suite reading that on knowledge questions the modal answer can be a confident misconception. Agnes2.5-Flash contributes the counter-case that bounds the mechanism: its SAT-Math and GSM8K floors sit near ceiling (S1 98.3 and 94.2), its pooled prompt-space aggregation margin is correspondingly small ($\Delta$PE +2.4), and on LogiQA the Agnes3.0 ordering reverses (PE-6 80.0 against SC-6 70.0, $\Delta$PE +2.5 against $\Delta$SC $-$3.3), so on stem-locus datasets the PE--SC ordering is a property of the model--paraphrase interaction rather than of the dataset. The DeepSeek models sharpen the same caution with opposite difficulty signs: DeepSeekV4.1's LogiQA paraphrases are 12.5 points easier at the single-call level (PE-1 65.0 against S1 52.5) --- where Agnes3.0's were 11.7 points harder --- and there the sample vote is again the only condition that aggregates a gain ($\Delta$SC +7.5 against $\Delta$PE +0.0), while its SAT-Math repeats the computation-deterministic direction ($\Delta$SC $-$0.8, $\Delta$PE +5.8) and its TruthfulQA supplies the counter-case to Agnes3.0's, with the sample vote helping ($\Delta$SC +5.0). The pro-tier DeepSeek shows the pool's largest single-call difficulty margins in both directions. Its LogiQA paraphrases are 14.1 points easier (PE-1 68.3 against S1 54.2); the paraphrase ensemble holds that base-rate advantage through voting (PE-6 70.0 against SC-6 55.0), but the within-family gains are small ($\Delta$PE +1.7 against $\Delta$SC +0.8), so what moves this cell is the difficulty margin rather than aggregation --- the mirror image of Agnes3.0's LogiQA. On PIQA its paraphrases are 6.7 points harder and the paraphrase ensemble loses to the sample ensemble by fifteen points (PE-6 80.0 against SC-6 95.0; measured against S1 the paraphrase side loses 10.0 points, of which 6.7 is the harder single-call base and $-$3.3 the within-family change, while the sample side gains $\Delta$SC +5.0). Pooled over the four models, the computation-deterministic datasets carry the paraphrase aggregation advantage (SAT-Math $\Delta$PE +7.5 against $\Delta$SC +0.0; GSM8K +2.1 against +0.8), while on LogiQA the sample side aggregates the larger gain ($\Delta$SC +5.0 against $\Delta$PE +1.5), the paraphrases' pooled single-call advantage there ($+$4.7 over S1) doing more of the work than aggregation, and TruthfulQA is neutral in aggregate ($\Delta$SC +0.8, $\Delta$PE +3.1). Two readings of these cells deserve explicit caution. First, the single-call difficulty margins of the same dataset's paraphrases swing by more than twelve points across models (LogiQA: $-$11.7 on Agnes3.0, $+$12.5 on DeepSeekV4.1, $+$14.1 on the pro tier) --- too large to dismiss as sampling noise at these denominators, and consistent either with specific rewrites shifting the task for specific models or with equivalence failures that the aggregate validation filters cannot see; the model--paraphrase interaction is real but not currently predictable, and we treat it as descriptive. Second, because each cell is a twenty-question stratum, individual margins carry wide intervals; the transferable content is the pair of directions --- paraphrase aggregation pays where resampling is exhausted and reverses where paraphrases shift the task --- rather than any single cell's magnitude."""

rep("The dataset decomposition carries the mechanism.",
    "The stratum structure of the main suite replicates",
    MECH + "\n\n", "P4-mechanism")

# ---- P5: strata paragraph (decomposition, not replication) ----
STRATA = r"""The strata defined on the development suite also organize the held-out votes, and the decomposition --- computed on the same twelve votes that define the pooled contrasts --- locates where the (statistically unresolved) PE$-$SC margin concentrates. The weak-majority stratum (mode share below two-thirds) holds 24, 8, 14, and 15 questions for the four models: PE-6 scores 58.3\% against 33.3\% for SC-6 and 31.9\% for S1 on Agnes3.0, 50.0\% against 25.0\% and 27.1\% on Agnes2.5, 50.0\% against 35.7\% and 33.3\% on DeepSeekV4.1, and 53.3\% against 33.3\% and 31.1\% on the pro tier; averaging the four models' strata (61 pairs in total) gives PE-6 52.9\% against 31.8\% for SC-6 and 30.9\% for S1, a $+$22-point margin exactly where answer-space votes have the least to aggregate, and for the two DeepSeek models the combined twelve-vote ensemble adds a further margin on top (COMB-12 57.1\% against PE-6 50.0\% on V4.1; 60.0\% against 53.3\% on the pro tier). We emphasize what this decomposition is and is not: it reuses the same votes that produce the pooled PE$-$SC gap of $+2.5$ points (interval touching zero), so it is a localization of that gap, not an independent replication of it, and part of the concentration is mechanical --- a question on which the sample side is degenerate but wrong is exactly a question where only the paraphrase side can move the answer, so the stratum where PE can win is selected, in part, by the failure of SC. The unanimous stratum ($n=70$, $n=90$, $n=69$, and $n=73$) is saturated at 96.3\% pooled under every condition, and the strong-majority stratum ($n=25$, $n=21$, $n=36$, and $n=31$) sits between, with the two six-vote ensembles at 76--77\% against an S1 of 67.0\%. The $\tau=0$ anomaly, by contrast, appears on exactly one of the four models, and the split is informative. On the two Agnes endpoints S1 minus greedy is $-$1.1 and $-$1.8 points, and on the pro-tier DeepSeek $-$1.0. On the direct-answer DeepSeekV4.1 endpoint the development-suite signature reappears: greedy sits 4.5 points below S1 (73.1\% against 77.6\%), and auditing its 16 off-mode greedy answers shows 13 of them wrong, with completion lengths of one to eleven characters --- genuine divergence between the temperature-zero answer and the sampled mode, not the truncation artifact of the development suite; the pro-tier sibling's 14 off-mode answers split 10 wrong against 4 right, a third clean case. Pooled, 50 of 476 greedy answers (10.5\%) fall outside the six-sample mode. This relocates the greedy audit's lesson: the temperature-zero failure is a property of the model--endpoint configuration rather than of the question draw or of a universal decoding pathology --- absent on three of four held-out endpoints, present without truncation on the fourth --- so practitioners should verify greedy against the sampled expectation per deployment rather than assume either baseline."""

rep("The stratum structure of the main suite replicates",
    "The adaptive allocation rule was designed",
    STRATA + "\n\n", "P5-strata")

# ---- P6: adaptive paragraph fixes ----
txt = txt.replace(
    "the first model in either suite on which the rule strictly dominates every fixed allocation; its probe routes",
    "the only model in either suite on which the rule exceeds every fixed allocation --- though the margin over the best of them is a single question, so we read it as reaching the fixed frontier rather than dominating it; its probe routes")
txt = txt.replace(
    "The adaptive allocation rule was designed on the main-suite matrices, so the expansion set supplies the fresh-question transfer test",
    "The adaptive allocation rule was designed on the development-suite matrices, so the held-out set supplies the fresh-question transfer test")
txt = txt.replace(
    "The main-suite conclusion therefore needs its fresh-question amendment: the rule saves 13 to 21 percent of the calls, strictly dominating every fixed allocation on one model and losing at most one question to the best fixed strategy on two others, but on Agnes3.0 it sits seven questions below the paraphrase vote",
    "The development-suite conclusion therefore needs its held-out amendment: the rule saves 13 to 21 percent of the calls, exceeds every fixed allocation on one model (by a single question), loses one question to its best fixed condition on the pro tier and two to PE-6 on Agnes2.5, and sits seven questions below the paraphrase vote on Agnes3.0")
print("patched: P6-adaptive")

# ---- P7: closing paragraph ----
CLOSE = r"""These results qualify, without overturning, the development-suite null. Read together, the two suites say that six-call sample-space ensembling moves accuracy little for any model in either suite (per-model $\Delta$SC between $-$3.3 and $+$2.7 points), while prompt-space ensembling produces the largest well-powered gains --- pooled $+$4.9 points over S1 on the held-out set (CI $+$2.3 to $+$7.6), of which $+$1.9 is a single-call difficulty offset and $+$3.0 the within-family aggregation gain, against $+$2.4 for self-consistency (CI $+$1.1 to $+$3.7) --- and it does so only where two conditions hold jointly: answer-space diversity is exhausted, as on computation-deterministic tasks where six samples re-derive the same wrong arithmetic, and paraphrases preserve task semantics. Where paraphrases distort the task, as on Agnes3.0's LogiQA subset or the pro-tier DeepSeek's PIQA subset, the advantage reverses. Which allocation realizes the margin is model-dependent --- the pure paraphrase vote on the two Agnes models, the hybrid and combined allocations on DeepSeekV4.1, the combined ensemble and self-consistency on its pro-tier sibling --- so the transferable content is the two qualifying conditions rather than a recipe. The gain is established here for four fully covered models from two providers and two families (two Agnes generations, two DeepSeek tiers) on one fresh draw, so we read it as a demonstrated possibility with an identified mechanism rather than as a universal effect."""

# ---- P7: closing paragraph (runs to end of file) ----
i = txt.find("These results qualify, without overturning, the main-suite null.")
if i < 0:
    sys.exit("P7: anchor not found")
txt = txt[:i] + CLOSE + "\n"
print("patched: P7-closing")

open(P, "w").write(txt)
print(f"\nwrote {P}: {len(orig)} -> {len(txt)} chars")
